import math
from functools import reduce

def gcd(a, b):
    return math.gcd(a, b)

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a*b) // gcd(a, b)

def list_gcd(numbers):
    if not numbers:
        return 0
    return reduce(gcd, numbers)

def list_lcm(numbers):
    if not numbers:
        return 1
    return reduce(lcm, numbers)

def count_good_partitions(sequence):
    n = len(sequence)
    if n < 2:
        return 0

    count = 0
    for k in range(1, n):
        A_k = sequence[:k]
        B_k = sequence[k:]

        lcm_Ak = list_lcm(A_k)
        gcd_Bk = list_gcd(B_k)

        if lcm_Ak == gcd_Bk:
            count += 1
            # print(f"k={k} is GOOD. LCM({A_k})={lcm_Ak}, GCD({B_k})={gcd_Bk}")
        # else:
        #     print(f"k={k} is NOT good. LCM({A_k})={lcm_Ak}, GCD({B_k})={gcd_Bk}")

    return count

# Test sequences for n=6
N6_seq1 = [1, 2, 3, 4, 5, 6]
N6_seq2 = [1, 2, 4, 8, 16, 32]
N6_seq3 = [2, 3, 4, 6, 12, 24] # Highly structured divisors/multiples
N6_seq4 = [1, 3, 5, 7, 11, 13] # Primes/1

results_n6 = {
    "Seq1 (1, 2, 3, 4, 5, 6)": count_good_partitions(N6_seq1),
    "Seq2 (Powers of 2)": count_good_partitions(N6_seq2),
    "Seq3 (Divisors)": count_good_partitions(N6_seq3),
    "Seq4 (Primes)": count_good_partitions(N6_seq4)
}

# Test sequences for n=7
N7_seq1 = [1, 2, 3, 4, 5, 6, 7]
N7_seq2 = [1, 2, 4, 8, 16, 32, 64]
N7_seq3 = [1, 2, 4, 8, 16, 32, 64] # Same as above, need to check better structured one
N7_seq4 = [2, 3, 6, 12, 24, 48, 96]

results_n7 = {
    "Seq1 (1..7)": count_good_partitions(N7_seq1),
    "Seq2 (Powers of 2)": count_good_partitions(N7_seq2),
    "Seq4 (Divisors)": count_good_partitions(N7_seq4)
}

# Test sequences for n=8
N8_seq1 = [1, 2, 3, 4, 5, 6, 7, 8]
N8_seq2 = [1, 2, 4, 8, 16, 32, 64, 128]
N8_seq3 = [2, 3, 6, 12, 24, 48, 96, 192]

results_n8 = {
    "Seq1 (1..8)": count_good_partitions(N8_seq1),
    "Seq2 (Powers of 2)": count_good_partitions(N8_seq2),
    "Seq3 (Divisors)": count_good_partitions(N8_seq3)
}

print("--- N=6 Results ---")
for seq, count in results_n6.items():
    print(f"{seq}: {count}")

print("\n--- N=7 Results ---")
for seq, count in results_n7.items():
    print(f"{seq}: {count}")

print("\n--- N=8 Results ---")
for seq, count in results_n8.items():
    print(f"{seq}: {count}")
